"use strict";(globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init=globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init||[]).push([[22707],{92965(e,a,n){n.r(a),n.d(a,{assets:()=>l,contentTitle:()=>c,default:()=>u,frontMatter:()=>i,metadata:()=>o,toc:()=>t});const o=JSON.parse('{"id":"cursos/cleancode/modulos/manejo-errores/cuestionario","title":"cuestionario","description":"2. [Investigar] \xbfQu\xe9 es el patr\xf3n \\"Circuit Breaker\\" popularizado por Michael Nygard en \\"Release It!\\" y c\xf3mo se aplica al manejo de errores en sistemas distribuidos? \xbfQu\xe9 estados tiene un circuit breaker y c\xf3mo difiere de un simple try-catch?","source":"@site/docs/cursos/cleancode/modulos/06-manejo-errores/cuestionario.md","sourceDirName":"cursos/cleancode/modulos/06-manejo-errores","slug":"/cursos/cleancode/modulos/manejo-errores/cuestionario","permalink":"/sasf-temarios/cursos/cleancode/modulos/manejo-errores/cuestionario","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"private":true,"sidebar_class_name":"private","sidebar_label":"Cuestionario"},"sidebar":"cursosSidebar","previous":{"title":"Clase","permalink":"/sasf-temarios/cursos/cleancode/modulos/manejo-errores/clase"},"next":{"title":"Ejercicio","permalink":"/sasf-temarios/cursos/cleancode/modulos/manejo-errores/ejercicio"}}');var r=n(74848),s=n(28453);const i={private:!0,sidebar_class_name:"private",sidebar_label:"Cuestionario"},c=void 0,l={},t=[{value:"2. [Investigar] \xbfQu\xe9 es el patr\xf3n &quot;Circuit Breaker&quot; popularizado por Michael Nygard en &quot;Release It!&quot; y c\xf3mo se aplica al manejo de errores en sistemas distribuidos? \xbfQu\xe9 estados tiene un circuit breaker y c\xf3mo difiere de un simple try-catch?",id:"2-investigar-qu\xe9-es-el-patr\xf3n-circuit-breaker-popularizado-por-michael-nygard-en-release-it-y-c\xf3mo-se-aplica-al-manejo-de-errores-en-sistemas-distribuidos-qu\xe9-estados-tiene-un-circuit-breaker-y-c\xf3mo-difiere-de-un-simple-try-catch",level:3},{value:"3. [Investigar] \xbfQu\xe9 son las &quot;Excepciones Chequeadas&quot; en Java y por qu\xe9 las criticaron Bruce Eckel, Anders Hejlsberg (creador de C#) y otros l\xedderes de la industria? \xbfC\xf3mo resolvi\xf3 C# el problema que Java intent\xf3 resolver con checked exceptions?",id:"3-investigar-qu\xe9-son-las-excepciones-chequeadas-en-java-y-por-qu\xe9-las-criticaron-bruce-eckel-anders-hejlsberg-creador-de-c-y-otros-l\xedderes-de-la-industria-c\xf3mo-resolvi\xf3-c-el-problema-que-java-intent\xf3-resolver-con-checked-exceptions",level:3},{value:"4. [Investigar] \xbfQu\xe9 es &quot;Structured Logging&quot; y c\xf3mo se diferencia de simplemente &quot;poner contexto en el mensaje de la excepci\xf3n&quot;? \xbfQu\xe9 proponen herramientas como SLF4J con Markers y Mapped Diagnostic Context (MDC) para el manejo de errores en producci\xf3n?",id:"4-investigar-qu\xe9-es-structured-logging-y-c\xf3mo-se-diferencia-de-simplemente-poner-contexto-en-el-mensaje-de-la-excepci\xf3n-qu\xe9-proponen-herramientas-como-slf4j-con-markers-y-mapped-diagnostic-context-mdc-para-el-manejo-de-errores-en-producci\xf3n",level:3},{value:"5. [Conectar] La clase menciona <code>Optional&amp;#x3C;T&gt;</code> y el Null Object Pattern como alternativas a null. \xbfC\xf3mo maneja Rust el problema de &quot;ausencia de valor&quot; sin null y sin Optional? \xbfQu\xe9 es <code>Option&amp;#x3C;T&gt;</code> en Rust y c\xf3mo se diferencia del <code>Optional&amp;#x3C;T&gt;</code> de Java en t\xe9rminos de seguridad y ergonom\xeda?",id:"5-conectar-la-clase-menciona-optionalx3ct-y-el-null-object-pattern-como-alternativas-a-null-c\xf3mo-maneja-rust-el-problema-de-ausencia-de-valor-sin-null-y-sin-optional-qu\xe9-es-optionx3ct-en-rust-y-c\xf3mo-se-diferencia-del-optionalx3ct-de-java-en-t\xe9rminos-de-seguridad-y-ergonom\xeda",level:3},{value:"6. [Conectar] La clase habla de &quot;fail fast&quot; con <code>Objects.requireNonNull</code>. \xbfC\xf3mo se relaciona el fail fast con el concepto de &quot;Design by Contract&quot; de Bertrand Meyer? \xbfQu\xe9 ofrecen herramientas como <code>@NonNull</code> de Checker Framework m\xe1s all\xe1 de <code>Objects.requireNonNull</code>?",id:"6-conectar-la-clase-habla-de-fail-fast-con-objectsrequirenonnull-c\xf3mo-se-relaciona-el-fail-fast-con-el-concepto-de-design-by-contract-de-bertrand-meyer-qu\xe9-ofrecen-herramientas-como-nonnull-de-checker-framework-m\xe1s-all\xe1-de-objectsrequirenonnull",level:3},{value:"7. [Conectar] La clase menciona <code>@RestControllerAdvice</code> para manejo global de excepciones en Spring. \xbfQu\xe9 es &quot;Problem Details&quot; (RFC 9457, antes RFC 7807) y c\xf3mo Spring lo implementa? \xbfPor qu\xe9 es superior a usar un <code>ErrorResponse</code> personalizado como sugiere la clase?",id:"7-conectar-la-clase-menciona-restcontrolleradvice-para-manejo-global-de-excepciones-en-spring-qu\xe9-es-problem-details-rfc-9457-antes-rfc-7807-y-c\xf3mo-spring-lo-implementa-por-qu\xe9-es-superior-a-usar-un-errorresponse-personalizado-como-sugiere-la-clase",level:3},{value:"8. [Cuestionar] La clase recomienda &quot;nunca retornar null&quot;. Pero Java mismo retorna null en muchas APIs est\xe1ndar (<code>Map.get(key)</code>, <code>List.get(index)</code>, <code>System.getProperty()</code>). \xbfEs realista &quot;nunca retornar null&quot; cuando el ecosistema est\xe1ndar no lo cumple? \xbfQu\xe9 estrategia de &quot;boundary&quot; proponen autores como Michael Feathers para lidiar con APIs que retornan null?",id:"8-cuestionar-la-clase-recomienda-nunca-retornar-null-pero-java-mismo-retorna-null-en-muchas-apis-est\xe1ndar-mapgetkey-listgetindex-systemgetproperty-es-realista-nunca-retornar-null-cuando-el-ecosistema-est\xe1ndar-no-lo-cumple-qu\xe9-estrategia-de-boundary-proponen-autores-como-michael-feathers-para-lidiar-con-apis-que-retornan-null",level:3},{value:"9. [Cuestionar] La clase prefiere unchecked exceptions argumentando que las checked violan el Open/Closed Principle. \xbfQu\xe9 argumentos de defensa de las checked exceptions sostienen que en APIs cr\xedticas (ej. sistemas de vuelo, dispositivos m\xe9dicos), la verificabilidad forzada por el compilador es EXACTAMENTE lo que se necesita? \xbfHay dominios donde checked exceptions son apropiadas?",id:"9-cuestionar-la-clase-prefiere-unchecked-exceptions-argumentando-que-las-checked-violan-el-openclosed-principle-qu\xe9-argumentos-de-defensa-de-las-checked-exceptions-sostienen-que-en-apis-cr\xedticas-ej-sistemas-de-vuelo-dispositivos-m\xe9dicos-la-verificabilidad-forzada-por-el-compilador-es-exactamente-lo-que-se-necesita-hay-dominios-donde-checked-exceptions-son-apropiadas",level:3},{value:"10. [Cuestionar] La clase dice que <code>catch (Exception e) &amp;#x7B; e.printStackTrace(); &amp;#x7D;</code> es mala pr\xe1ctica. \xbfQu\xe9 dice la comunidad sobre el logging de excepciones a nivel de framework? \xbfExiste el riesgo de &quot;double logging&quot; (loggear la misma excepci\xf3n en m\xfaltiples capas) y c\xf3mo lo resuelve la pr\xe1ctica de &quot;log or rethrow, never both&quot;?",id:"10-cuestionar-la-clase-dice-que-catch-exception-e-x7b-eprintstacktrace-x7d-es-mala-pr\xe1ctica-qu\xe9-dice-la-comunidad-sobre-el-logging-de-excepciones-a-nivel-de-framework-existe-el-riesgo-de-double-logging-loggear-la-misma-excepci\xf3n-en-m\xfaltiples-capas-y-c\xf3mo-lo-resuelve-la-pr\xe1ctica-de-log-or-rethrow-never-both",level:3}];function d(e){const a={code:"code",h3:"h3",hr:"hr",p:"p",strong:"strong",...(0,s.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)(a.h3,{id:"2-investigar-qu\xe9-es-el-patr\xf3n-circuit-breaker-popularizado-por-michael-nygard-en-release-it-y-c\xf3mo-se-aplica-al-manejo-de-errores-en-sistemas-distribuidos-qu\xe9-estados-tiene-un-circuit-breaker-y-c\xf3mo-difiere-de-un-simple-try-catch",children:'2. [Investigar] \xbfQu\xe9 es el patr\xf3n "Circuit Breaker" popularizado por Michael Nygard en "Release It!" y c\xf3mo se aplica al manejo de errores en sistemas distribuidos? \xbfQu\xe9 estados tiene un circuit breaker y c\xf3mo difiere de un simple try-catch?'}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Respuesta"}),': Michael Nygard, en "Release It!" (2007, 2da edici\xf3n 2018), describi\xf3 el Circuit Breaker como patr\xf3n para manejar fallas en integraciones externas. Tiene tres estados: CLOSED (operaci\xf3n normal, las llamadas pasan), OPEN (el circuito se abre tras N fallas consecutivas, las llamadas se rechazan inmediatamente sin intentar la operaci\xf3n), HALF-OPEN (tras un timeout, se permite UNA llamada de prueba; si falla, vuelve a OPEN; si funciona, vuelve a CLOSED). Diferencia con try-catch: (a) el try-catch intenta SIEMPRE la operaci\xf3n y falla cada vez, el circuit breaker detecta fallas repetidas y deja de intentar protegiendo al sistema externo de sobrecarga, (b) el circuit breaker es stateful a trav\xe9s de m\xfaltiples llamadas, el try-catch maneja una llamada individual, (c) el circuit breaker implementa "fail fast" a nivel de infraestructura: si la BD est\xe1 ca\xedda, no malgast\xe1s threads esperando timeouts, rechaz\xe1s inmediatamente y liber\xe1s recursos. En Spring, Resilience4j implementa circuit breakers. Clean Code no aborda este patr\xf3n porque se enfoca en errores locales, no distribuidos.']}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Por qu\xe9"}),": La clase cubre manejo de errores dentro de un solo proceso. En el proyecto final del curso (Spring Boot), los alumnos integrar\xe1n servicios externos y necesitar\xe1n patrones de resiliencia. Nygard es la referencia fundamental en resiliencia de sistemas y su patr\xf3n complementa el manejo de excepciones local con estrategias de sistema."]}),"\n",(0,r.jsx)(a.hr,{}),"\n",(0,r.jsx)(a.h3,{id:"3-investigar-qu\xe9-son-las-excepciones-chequeadas-en-java-y-por-qu\xe9-las-criticaron-bruce-eckel-anders-hejlsberg-creador-de-c-y-otros-l\xedderes-de-la-industria-c\xf3mo-resolvi\xf3-c-el-problema-que-java-intent\xf3-resolver-con-checked-exceptions",children:'3. [Investigar] \xbfQu\xe9 son las "Excepciones Chequeadas" en Java y por qu\xe9 las criticaron Bruce Eckel, Anders Hejlsberg (creador de C#) y otros l\xedderes de la industria? \xbfC\xf3mo resolvi\xf3 C# el problema que Java intent\xf3 resolver con checked exceptions?'}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Respuesta"}),": Las excepciones chequeadas (checked) en Java son aquellas que el compilador obliga a declarar en ",(0,r.jsx)(a.code,{children:"throws"})," o capturar con ",(0,r.jsx)(a.code,{children:"try-catch"}),'. Fueron una innovaci\xf3n de Java 1.0. Las cr\xedticas: (a) Bruce Eckel (autor de "Thinking in Java") escribi\xf3 en 2003 "Does Java Need Checked Exceptions?" argumentando que incentivan malas pr\xe1cticas: los desarrolladores tragan excepciones con ',(0,r.jsx)(a.code,{children:"catch (Exception e) &#x7B;&#x7D;"})," o las envuelven en RuntimeException para evitar declararlas, anulando su prop\xf3sito; (b) Anders Hejlsberg (C# architect) decidi\xf3 NO incluir checked exceptions en C# argumentando que la verificabilidad de tipos en excepciones no escala: en un sistema grande, el throws clause de un m\xe9todo se vuelve extremadamente largo o las excepciones se generalizan a ",(0,r.jsx)(a.code,{children:"throws Exception"}),", eliminando el valor; (c) las lambdas de Java 8 no pueden lanzar checked exceptions, forzando workarounds. C# resolvi\xf3 el problema con: documentaci\xf3n XML de excepciones (opcional, no forzada por compilador) + an\xe1lisis est\xe1tico opcional. La comunidad Java ha migrado a unchecked exceptions en la pr\xe1ctica (Spring, Hibernate)."]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Por qu\xe9"}),': La clase menciona que Clean Code "prefiere unchecked exceptions" citando a Robert C. Martin, pero sin explorar el debate hist\xf3rico que llev\xf3 a esta conclusi\xf3n. Eckel y Hejlsberg hicieron contribuciones fundamentales al dise\xf1o de lenguajes. El alumno debe entender que las checked exceptions no son "malas" per se \u2014son un experimento de dise\xf1o de lenguaje que la industria evalu\xf3 y mayoritariamente rechaz\xf3.']}),"\n",(0,r.jsx)(a.hr,{}),"\n",(0,r.jsx)(a.h3,{id:"4-investigar-qu\xe9-es-structured-logging-y-c\xf3mo-se-diferencia-de-simplemente-poner-contexto-en-el-mensaje-de-la-excepci\xf3n-qu\xe9-proponen-herramientas-como-slf4j-con-markers-y-mapped-diagnostic-context-mdc-para-el-manejo-de-errores-en-producci\xf3n",children:'4. [Investigar] \xbfQu\xe9 es "Structured Logging" y c\xf3mo se diferencia de simplemente "poner contexto en el mensaje de la excepci\xf3n"? \xbfQu\xe9 proponen herramientas como SLF4J con Markers y Mapped Diagnostic Context (MDC) para el manejo de errores en producci\xf3n?'}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Respuesta"}),": Structured Logging (logging estructurado) es la pr\xe1ctica de loggear eventos como pares clave-valor en formato JSON/estructurado en lugar de strings planos. Un mensaje de excepci\xf3n tradicional: ",(0,r.jsx)(a.code,{children:'"Payment failed for customer 12345: balance 50.00 &#x3C; 75.00"'}),". Versi\xf3n estructurada: ",(0,r.jsx)(a.code,{children:'&#x7B;"event": "payment_failed", "customerId": "12345", "balance": 50.00, "required": 75.00, "errorCode": "INSUFFICIENT_FUNDS"&#x7D;'}),'. La diferencia: (a) los sistemas de agregaci\xf3n de logs (ELK, Splunk, Datadog) pueden indexar, buscar y graficar campos estructurados; no pueden hacer queries eficientes sobre strings planos, (b) MDC (Mapped Diagnostic Context) de SLF4J permite inyectar contexto autom\xe1ticamente en TODOS los logs de un request (requestId, userId, tenant) sin que cada excepci\xf3n los incluya manualmente, (c) los Markers de SLF4J permiten categorizar eventos (BUSINESS_ERROR, TECHNICAL_ERROR, SECURITY) para filtrar y enrutar logs. La clase dice "provee contexto en excepciones" pero no ense\xf1a que en sistemas modernos, el contexto debe ser ESTRUCTURADO para ser procesable por m\xe1quinas, no solo legible por humanos.']}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Por qu\xe9"}),': La clase se enfoca en el mensaje de excepci\xf3n legible por humanos. En producci\xf3n, los logs son consumidos por sistemas autom\xe1ticos. Structured logging es un est\xe1ndar de facto (todas las plataformas cloud lo recomiendan) y el alumno debe saber que "poner contexto" en 2026 significa proveer datos estructurados, no solo strings descriptivos.']}),"\n",(0,r.jsx)(a.hr,{}),"\n",(0,r.jsxs)(a.h3,{id:"5-conectar-la-clase-menciona-optionalx3ct-y-el-null-object-pattern-como-alternativas-a-null-c\xf3mo-maneja-rust-el-problema-de-ausencia-de-valor-sin-null-y-sin-optional-qu\xe9-es-optionx3ct-en-rust-y-c\xf3mo-se-diferencia-del-optionalx3ct-de-java-en-t\xe9rminos-de-seguridad-y-ergonom\xeda",children:["5. [Conectar] La clase menciona ",(0,r.jsx)(a.code,{children:"Optional&#x3C;T>"}),' y el Null Object Pattern como alternativas a null. \xbfC\xf3mo maneja Rust el problema de "ausencia de valor" sin null y sin Optional? \xbfQu\xe9 es ',(0,r.jsx)(a.code,{children:"Option&#x3C;T>"})," en Rust y c\xf3mo se diferencia del ",(0,r.jsx)(a.code,{children:"Optional&#x3C;T>"})," de Java en t\xe9rminos de seguridad y ergonom\xeda?"]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Respuesta"}),": Rust elimina ",(0,r.jsx)(a.code,{children:"null"})," del lenguaje por completo. Usa ",(0,r.jsx)(a.code,{children:"Option&#x3C;T>"})," (enum con dos variantes: ",(0,r.jsx)(a.code,{children:"Some(T)"})," y ",(0,r.jsx)(a.code,{children:"None"}),"), pero a diferencia de ",(0,r.jsx)(a.code,{children:"Optional&#x3C;T>"})," de Java: (a) ",(0,r.jsx)(a.code,{children:"Option&#x3C;T>"})," en Rust no es nullable \u2014un ",(0,r.jsx)(a.code,{children:"Option&#x3C;T>"})," NUNCA es null, a diferencia de ",(0,r.jsx)(a.code,{children:"Optional"})," de Java que PUEDE ser null (ej. ",(0,r.jsx)(a.code,{children:"Optional.of(null)"})," lanza NPE, pero ",(0,r.jsx)(a.code,{children:"Optional.ofNullable(null)"})," retorna ",(0,r.jsx)(a.code,{children:"Optional.empty()"})," \u2014y alguien puede pasar ",(0,r.jsx)(a.code,{children:"null"})," donde se espera ",(0,r.jsx)(a.code,{children:"Optional"}),"), (b) Rust tiene pattern matching exhaustivo: el compilador OBLIGA a cubrir ambos casos ",(0,r.jsx)(a.code,{children:"Some"})," y ",(0,r.jsx)(a.code,{children:"None"})," en cada ",(0,r.jsx)(a.code,{children:"match"}),"; en Java pod\xe9s llamar a ",(0,r.jsx)(a.code,{children:".get()"})," sin verificar y obten\xe9s ",(0,r.jsx)(a.code,{children:"NoSuchElementException"}),", (c) Rust provee el operador ",(0,r.jsx)(a.code,{children:"?"})," para propagaci\xf3n temprana de ",(0,r.jsx)(a.code,{children:"None"})," (similar al ",(0,r.jsx)(a.code,{children:"?."})," de Kotlin pero a nivel de funci\xf3n y tipado), (d) ",(0,r.jsx)(a.code,{children:"Option"})," en Rust tiene zero-cost abstraction (el compilador optimiza ",(0,r.jsx)(a.code,{children:"Option&#x3C;&T>"})," a un puntero nullable a nivel m\xe1quina, sin overhead). La diferencia fundamental: en Java, ",(0,r.jsx)(a.code,{children:"Optional"})," es una herramienta de biblioteca que convive con null; en Rust, ",(0,r.jsx)(a.code,{children:"Option"})," es parte del sistema de tipos y null NO EXISTE como concepto del lenguaje."]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Por qu\xe9"}),": La clase presenta Optional como la soluci\xf3n, pero no discute sus limitaciones en Java (Optional mismo puede ser null, no es serializable para JPA, no se puede usar como par\xe1metro de m\xe9todo seg\xfan Brian Goetz). Rust muestra c\xf3mo un lenguaje dise\xf1ado desde cero resuelve el problema de ra\xedz. El contraste ayuda al alumno a entender que Clean Code hace lo mejor posible con las herramientas de Java, pero el problema de null es una limitaci\xf3n del lenguaje."]}),"\n",(0,r.jsx)(a.hr,{}),"\n",(0,r.jsxs)(a.h3,{id:"6-conectar-la-clase-habla-de-fail-fast-con-objectsrequirenonnull-c\xf3mo-se-relaciona-el-fail-fast-con-el-concepto-de-design-by-contract-de-bertrand-meyer-qu\xe9-ofrecen-herramientas-como-nonnull-de-checker-framework-m\xe1s-all\xe1-de-objectsrequirenonnull",children:['6. [Conectar] La clase habla de "fail fast" con ',(0,r.jsx)(a.code,{children:"Objects.requireNonNull"}),'. \xbfC\xf3mo se relaciona el fail fast con el concepto de "Design by Contract" de Bertrand Meyer? \xbfQu\xe9 ofrecen herramientas como ',(0,r.jsx)(a.code,{children:"@NonNull"})," de Checker Framework m\xe1s all\xe1 de ",(0,r.jsx)(a.code,{children:"Objects.requireNonNull"}),"?"]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Respuesta"}),': Bertrand Meyer introdujo "Design by Contract" (DbC) en el lenguaje Eiffel (1986, "Object-Oriented Software Construction"). DbC define tres tipos de aserciones: precondiciones (lo que el caller debe garantizar), postcondiciones (lo que el m\xe9todo garantiza al retornar), invariantes (lo que la clase garantiza siempre). ',(0,r.jsx)(a.code,{children:"Objects.requireNonNull"})," es una precondici\xf3n escrita manualmente. El Checker Framework (desarrollado por Michael Ernst y su equipo en University of Washington, integrable en Java) va m\xe1s all\xe1: con la anotaci\xf3n ",(0,r.jsx)(a.code,{children:"@NonNull"}),", el compilador verifica en TIEMPO DE COMPILACI\xd3N que ning\xfan valor potencialmente null llegue a un par\xe1metro anotado como ",(0,r.jsx)(a.code,{children:"@NonNull"})," \u2014a trav\xe9s de TODA la cadena de llamadas del programa. La diferencia: (a) ",(0,r.jsx)(a.code,{children:"requireNonNull"})," es tiempo de ejecuci\xf3n (fail fast en runtime), (b) ",(0,r.jsx)(a.code,{children:"@NonNull"})," de Checker Framework es tiempo de compilaci\xf3n (fail fast antes de ejecutar), (c) DbC con Eiffel chequea precondiciones autom\xe1ticamente en testing/desarrollo. La evoluci\xf3n: fail fast comenz\xf3 en runtime, la industria avanza hacia fail fast en compilaci\xf3n."]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Por qu\xe9"}),': La clase recomienda fail fast pero no explora el "Design by Contract" que es la teor\xeda fundacional detr\xe1s de la validaci\xf3n de entrada. Meyer es una figura central en ingenier\xeda de software y el Checker Framework demuestra que las limitaciones de null en Java pueden mitigarse con tooling avanzado sin cambiar de lenguaje. Esto complementa el m\xf3dulo con herramientas modernas.']}),"\n",(0,r.jsx)(a.hr,{}),"\n",(0,r.jsxs)(a.h3,{id:"7-conectar-la-clase-menciona-restcontrolleradvice-para-manejo-global-de-excepciones-en-spring-qu\xe9-es-problem-details-rfc-9457-antes-rfc-7807-y-c\xf3mo-spring-lo-implementa-por-qu\xe9-es-superior-a-usar-un-errorresponse-personalizado-como-sugiere-la-clase",children:["7. [Conectar] La clase menciona ",(0,r.jsx)(a.code,{children:"@RestControllerAdvice"}),' para manejo global de excepciones en Spring. \xbfQu\xe9 es "Problem Details" (RFC 9457, antes RFC 7807) y c\xf3mo Spring lo implementa? \xbfPor qu\xe9 es superior a usar un ',(0,r.jsx)(a.code,{children:"ErrorResponse"})," personalizado como sugiere la clase?"]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Respuesta"}),': RFC 9457 (antes RFC 7807, "Problem Details for HTTP APIs", 2016) define un formato est\xe1ndar para respuestas de error HTTP: ',(0,r.jsx)(a.code,{children:'&#x7B;"type": "https://api.example.com/errors/insufficient-funds", "title": "Insufficient Funds", "status": 400, "detail": "Account 12345 has balance 50.00 but required 75.00", "instance": "/payments/789"&#x7D;'}),". Spring implementa esto con ",(0,r.jsx)(a.code,{children:"ProblemDetail"})," (desde Spring Framework 6 / Boot 3) y ",(0,r.jsx)(a.code,{children:"ErrorResponse"}),". Es superior a un ",(0,r.jsx)(a.code,{children:"ErrorResponse"})," personalizado porque: (a) es un EST\xc1NDAR \u2014cualquier cliente HTTP que consuma tu API (Postman, curl, otros microservicios) puede parsear el error sin documentaci\xf3n personalizada, (b) los campos ",(0,r.jsx)(a.code,{children:"type"})," (URI que identifica el tipo de error), ",(0,r.jsx)(a.code,{children:"instance"})," (URI del recurso que caus\xf3 el error), y ",(0,r.jsx)(a.code,{children:"title"})," son sem\xe1nticamente precisos y permiten automatizaci\xf3n, (c) herramientas de monitoreo y API Gateways pueden procesar Problem Details autom\xe1ticamente. La clase propone crear ",(0,r.jsx)(a.code,{children:"ErrorResponse"})," propio, lo cual es comprensible pre-2016, pero hoy usar el est\xe1ndar es m\xe1s interoperable."]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Por qu\xe9"}),": La clase usa un formato de error ad-hoc. La RFC 9457 es el est\xe1ndar moderno y Spring lo soporta nativamente. El alumno debe conocer que para APIs HTTP, existen est\xe1ndares que reemplazan soluciones caseras."]}),"\n",(0,r.jsx)(a.hr,{}),"\n",(0,r.jsxs)(a.h3,{id:"8-cuestionar-la-clase-recomienda-nunca-retornar-null-pero-java-mismo-retorna-null-en-muchas-apis-est\xe1ndar-mapgetkey-listgetindex-systemgetproperty-es-realista-nunca-retornar-null-cuando-el-ecosistema-est\xe1ndar-no-lo-cumple-qu\xe9-estrategia-de-boundary-proponen-autores-como-michael-feathers-para-lidiar-con-apis-que-retornan-null",children:['8. [Cuestionar] La clase recomienda "nunca retornar null". Pero Java mismo retorna null en muchas APIs est\xe1ndar (',(0,r.jsx)(a.code,{children:"Map.get(key)"}),", ",(0,r.jsx)(a.code,{children:"List.get(index)"}),", ",(0,r.jsx)(a.code,{children:"System.getProperty()"}),'). \xbfEs realista "nunca retornar null" cuando el ecosistema est\xe1ndar no lo cumple? \xbfQu\xe9 estrategia de "boundary" proponen autores como Michael Feathers para lidiar con APIs que retornan null?']}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Respuesta"}),': "Nunca retornar null" es un ideal de dise\xf1o para TU c\xf3digo, no una regla para wrappers de APIs externas. Las APIs del JDK que retornan null preceden a ',(0,r.jsx)(a.code,{children:"Optional"}),' (introducido en Java 8, 2014). Michael Feathers sugiere en "Working Effectively with Legacy Code" la estrategia de "seam": cre\xe1 una DELGADA capa de adaptaci\xf3n (seam) alrededor de las APIs externas que retornan null, y en TU c\xf3digo de dominio nunca retornes null. Ejemplo: en lugar de propagar ',(0,r.jsx)(a.code,{children:"Map.get(key)"})," que puede retornar null, cre\xe1s un m\xe9todo ",(0,r.jsx)(a.code,{children:"getRequired(key)"})," que lanza excepci\xf3n o retorna ",(0,r.jsx)(a.code,{children:"Optional"}),". La capa de adaptaci\xf3n es ESTRECHA (pocas l\xedneas, cerca del boundary) y contamina m\xednimamente. El realismo: tu c\xf3digo de negocio usa ",(0,r.jsx)(a.code,{children:"Optional"}),' y nunca ve null; tu capa de adaptaci\xf3n maneja los nulls del JDK/librer\xedas en los bordes. La regla es "minimiz\xe1 la superficie donde null puede aparecer". El alumno debe entender que Clean Code describe un IDEAL, y la ingenier\xeda consiste en gestionar la distancia entre el ideal y la realidad con patrones de contenci\xf3n.']}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Por qu\xe9"}),': La clase da una regla absoluta que ning\xfan proyecto Java real puede cumplir sin wrappers. Feathers provee la estrategia de contenci\xf3n que transforma la regla en pr\xe1ctica. El alumno debe saber que "nunca retornar null" significa "nunca retornar null en tu API de dominio", no "reescrib\xed el JDK".']}),"\n",(0,r.jsx)(a.hr,{}),"\n",(0,r.jsx)(a.h3,{id:"9-cuestionar-la-clase-prefiere-unchecked-exceptions-argumentando-que-las-checked-violan-el-openclosed-principle-qu\xe9-argumentos-de-defensa-de-las-checked-exceptions-sostienen-que-en-apis-cr\xedticas-ej-sistemas-de-vuelo-dispositivos-m\xe9dicos-la-verificabilidad-forzada-por-el-compilador-es-exactamente-lo-que-se-necesita-hay-dominios-donde-checked-exceptions-son-apropiadas",children:"9. [Cuestionar] La clase prefiere unchecked exceptions argumentando que las checked violan el Open/Closed Principle. \xbfQu\xe9 argumentos de defensa de las checked exceptions sostienen que en APIs cr\xedticas (ej. sistemas de vuelo, dispositivos m\xe9dicos), la verificabilidad forzada por el compilador es EXACTAMENTE lo que se necesita? \xbfHay dominios donde checked exceptions son apropiadas?"}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Respuesta"}),": En sistemas de alta criticidad (avi\xf3nica DO-178C, dispositivos m\xe9dicos IEC 62304, sistemas financieros con requisitos regulatorios), la verificabilidad en tiempo de compilaci\xf3n es un REQUISITO, no una preferencia. En estos dominios, las checked exceptions forzan al programador a considerar cada modo de falla: no pod\xe9s OLVIDARTE de manejar un ",(0,r.jsx)(a.code,{children:"IOException"}),' porque el compilador no te deja compilar. Esto se alinea con la filosof\xeda de "correctness by construction". James Gosling defendi\xf3 las checked exceptions exactamente con este argumento: en sistemas donde un error no manejado puede causar p\xe9rdida de vidas o millones de d\xf3lares, el compilador debe ser un aliado que imponga disciplina. El problema no son las checked exceptions en S\xcd, sino que Java las APLIC\xd3 INDISCRIMINADAMENTE a todas las APIs \u2014incluyendo ',(0,r.jsx)(a.code,{children:"SQLException"})," en un CRUD simple. En dominios cr\xedticos, checked exceptions + herramientas de an\xe1lisis est\xe1tico (que verifican que cada modo de falla tiene un handler documentado) es la combinaci\xf3n correcta. Clean Code asume desarrollo de software empresarial, no sistemas cr\xedticos."]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Por qu\xe9"}),': La clase generaliza desde software empresarial. El alumno debe entender que las reglas de Clean Code tienen contexto y que en dominios regulados, "checked exceptions violan OCP" cede ante "el compilador debe garantizar que ning\xfan error pase desapercibido". Conocer los l\xedmites de aplicabilidad de los principios es se\xf1al de seniority.']}),"\n",(0,r.jsx)(a.hr,{}),"\n",(0,r.jsxs)(a.h3,{id:"10-cuestionar-la-clase-dice-que-catch-exception-e-x7b-eprintstacktrace-x7d-es-mala-pr\xe1ctica-qu\xe9-dice-la-comunidad-sobre-el-logging-de-excepciones-a-nivel-de-framework-existe-el-riesgo-de-double-logging-loggear-la-misma-excepci\xf3n-en-m\xfaltiples-capas-y-c\xf3mo-lo-resuelve-la-pr\xe1ctica-de-log-or-rethrow-never-both",children:["10. [Cuestionar] La clase dice que ",(0,r.jsx)(a.code,{children:"catch (Exception e) &#x7B; e.printStackTrace(); &#x7D;"}),' es mala pr\xe1ctica. \xbfQu\xe9 dice la comunidad sobre el logging de excepciones a nivel de framework? \xbfExiste el riesgo de "double logging" (loggear la misma excepci\xf3n en m\xfaltiples capas) y c\xf3mo lo resuelve la pr\xe1ctica de "log or rethrow, never both"?']}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Respuesta"}),': La pr\xe1ctica "log or rethrow, never both" (logge\xe1 o relanz\xe1, nunca ambos) es un est\xe1ndar de la comunidad Java (documentado en las gu\xedas de estilo de Google, en Effective Java de Joshua Bloch, Item 63 y 75). El problema: si el servicio loggea la excepci\xf3n Y la relanza, y el controller advice tambi\xe9n la loggea, la misma excepci\xf3n aparece 2+ veces en los logs, creando confusi\xf3n en la correlaci\xf3n de eventos y llenando el storage de logs. La regla: cada excepci\xf3n debe ser loggeada UNA SOLA VEZ, en el nivel M\xc1S EXTERNO que tiene contexto suficiente. En una arquitectura Spring t\xedpica: el servicio lanza la excepci\xf3n con contexto rico; el ',(0,r.jsx)(a.code,{children:"@RestControllerAdvice"}),' la captura, loggea UNA vez con el requestId del MDC, y retorna la respuesta HTTP. Las capas intermedias NUNCA loggean y relanzan \u2014solo agregan contexto con "exception chaining" (pasan la causa original). La clase solo dice "no uses printStackTrace" pero no ense\xf1a la estrategia de logging en capas, que es donde los equipos reales sufren.']}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Por qu\xe9"}),": La clase critica ",(0,r.jsx)(a.code,{children:"printStackTrace"}),' sin proveer la alternativa arquitect\xf3nica. "Log or rethrow" es el complemento necesario para que la recomendaci\xf3n de la clase sea accionable. Bloch (Effective Java) es lectura obligatoria para cualquier desarrollador Java y provee la justificaci\xf3n detallada de esta pr\xe1ctica.']})]})}function u(e={}){const{wrapper:a}={...(0,s.R)(),...e.components};return a?(0,r.jsx)(a,{...e,children:(0,r.jsx)(d,{...e})}):d(e)}},28453(e,a,n){n.d(a,{R:()=>i,x:()=>c});var o=n(96540);const r={},s=o.createContext(r);function i(e){const a=o.useContext(s);return o.useMemo(function(){return"function"==typeof e?e(a):{...a,...e}},[a,e])}function c(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:i(e.components),o.createElement(s.Provider,{value:a},e.children)}}}]);